import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireAssert Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireAssert/aireassert-v1-3-5.md","filePath":"aireblock-releases/AireAssert/aireassert-v1-3-5.md","lastUpdated":1788524097000}`),a={name:`aireblock-releases/AireAssert/aireassert-v1-3-5.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireassert-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireassert-icon.png"> AireAssert Release Notes</span> <a class="header-anchor" href="#aireassert-release-notes" aria-label="Permalink to “AireAssert Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 1.3.5<br><strong>Release Date:</strong> 9 September 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Import Features Within the Same File (AA-918)</li><li>Updated Third-Party Dependencies (AA-999)</li><li>Consistent ID and Label Referencing in the Test Runner (AA-1006)</li><li>Detect Successful Submission for Redirecting Forms (AA-1015)</li><li>Improved Code Completion Suggestions (AA-1024)</li><li>Hover for Code Completion Details (AA-1026)</li><li>View Recordings Without Downloading (AA-1030)</li><li>Download Test Log Results (AA-1031)</li><li>Automatic TOTP Extraction from QR Codes (AA-1033)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Code Completion for Scenario References (AA-1009)</li><li>Fixed Patient Form Submission Test Failure (AA-1018)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="import-features-within-the-same-file-aa-918" tabindex="-1">Import Features Within the Same File (AA-918) <a class="header-anchor" href="#import-features-within-the-same-file-aa-918" aria-label="Permalink to “Import Features Within the Same File (AA-918)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Aire Assert now supports importing features directly within the same file they&#39;re used in, rather than requiring them to be defined in separate files. Existing imports from external files continue to work exactly as before.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now define and reuse smaller, related features in one file, making your test suites more concise and easier to manage.</p></div><h4 id="updated-third-party-dependencies-aa-999" tabindex="-1">Updated Third-Party Dependencies (AA-999) <a class="header-anchor" href="#updated-third-party-dependencies-aa-999" aria-label="Permalink to “Updated Third-Party Dependencies (AA-999)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>A third-party library used within Aire Assert has been updated to the latest version to address a known security vulnerability.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You&#39;re automatically protected by this update, with no changes required on your part.</p></div><h4 id="consistent-id-and-label-referencing-in-the-test-runner-aa-1006" tabindex="-1">Consistent ID and Label Referencing in the Test Runner (AA-1006) <a class="header-anchor" href="#consistent-id-and-label-referencing-in-the-test-runner-aa-1006" aria-label="Permalink to “Consistent ID and Label Referencing in the Test Runner (AA-1006)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The way the test runner resolves references to controls and elements by ID versus Label has been reviewed and made consistent: a reference prefixed with <code>#</code> is always treated as an ID, while an unprefixed reference is checked as an ID first, then falls back to a Label.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When writing test steps, you can now rely on ID and Label references behaving the same way everywhere in the runner, making your tests more predictable.</p></div><h4 id="detect-successful-submission-for-redirecting-forms-aa-1015" tabindex="-1">Detect Successful Submission for Redirecting Forms (AA-1015) <a class="header-anchor" href="#detect-successful-submission-for-redirecting-forms-aa-1015" aria-label="Permalink to “Detect Successful Submission for Redirecting Forms (AA-1015)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Aire Assert can now detect a successful submission for forms that redirect to another page afterwards, rather than only recognising success on the same page.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If your forms redirect after submission, your tests can now confirm success reliably without extra workarounds.</p></div><h4 id="improved-code-completion-suggestions-aa-1024" tabindex="-1">Improved Code Completion Suggestions (AA-1024) <a class="header-anchor" href="#improved-code-completion-suggestions-aa-1024" aria-label="Permalink to “Improved Code Completion Suggestions (AA-1024)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Code completion suggestions have been simplified so each control appears once, shown as &quot;Label - #id&quot;, rather than duplicated with the label and ID reversed. Searching or filtering still matches against both the label and the ID, and a <code>#</code>-prefixed search still shows the ID first.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Code completion now shows clearer, non-duplicated suggestions, making it quicker to find the control you&#39;re looking for.</p></div><h4 id="hover-for-code-completion-details-aa-1026" tabindex="-1">Hover for Code Completion Details (AA-1026) <a class="header-anchor" href="#hover-for-code-completion-details-aa-1026" aria-label="Permalink to “Hover for Code Completion Details (AA-1026)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>You can now hover over items with code completion available to see additional information, rather than needing to press Ctrl+Space.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If you prefer using your mouse over keyboard shortcuts, you can now see extra detail on code completion items just by hovering over them.</p></div><h4 id="view-recordings-without-downloading-aa-1030" tabindex="-1">View Recordings Without Downloading (AA-1030) <a class="header-anchor" href="#view-recordings-without-downloading-aa-1030" aria-label="Permalink to “View Recordings Without Downloading (AA-1030)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Test recordings can now be opened and viewed in a new browser tab, instead of only being available as a download. A download option remains available.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now quickly watch a recording in your browser without downloading it to your device first.</p></div><h4 id="download-test-log-results-aa-1031" tabindex="-1">Download Test Log Results (AA-1031) <a class="header-anchor" href="#download-test-log-results-aa-1031" aria-label="Permalink to “Download Test Log Results (AA-1031)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>You can now download the results of test logs directly.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can save your test log results locally for sharing or record-keeping.</p></div><h4 id="automatic-totp-extraction-from-qr-codes-aa-1033" tabindex="-1">Automatic TOTP Extraction from QR Codes (AA-1033) <a class="header-anchor" href="#automatic-totp-extraction-from-qr-codes-aa-1033" aria-label="Permalink to “Automatic TOTP Extraction from QR Codes (AA-1033)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Creating a new AireFrame test user previously required manually extracting a TOTP secret from a QR code. You can now upload the QR code and have the TOTP secret extracted automatically.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Setting up test users with two-factor authentication is now much quicker — just upload the QR code instead of manually extracting the secret.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="code-completion-for-scenario-references-aa-1009" tabindex="-1">Code Completion for Scenario References (AA-1009) <a class="header-anchor" href="#code-completion-for-scenario-references-aa-1009" aria-label="Permalink to “Code Completion for Scenario References (AA-1009)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Code completion has been added for the &quot;GIVEN we have run scenario&quot; statement, suggesting other scenarios in the same feature file as well as any imported via an Import statement.</p></div><h4 id="fixed-patient-form-submission-test-failure-aa-1018" tabindex="-1">Fixed Patient Form Submission Test Failure (AA-1018) <a class="header-anchor" href="#fixed-patient-form-submission-test-failure-aa-1018" aria-label="Permalink to “Fixed Patient Form Submission Test Failure (AA-1018)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue causing a patient form submission test to fail incorrectly.</p></div>`,42)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};